import os
import shutil

def main():
    print("--- BEGINNING GROUND TRUTH RESTORATION FOR STUDY 002 ---")

    source_dir = "storage/telos/repro_studies/study_002_axiom_agency_lab/ground_truth"

    destinations = {
        'axiom_report_v1_2b_interactions_official_v2_1.txt': 'storage/shared/agency_lab/analyses/',
        'f1_per_agent.csv': 'storage/shared/agency_lab/analyses/csv/',
        'f2_novelty_timeline.csv': 'storage/shared/agency_lab/analyses/csv/',
        'f3_timesliced_combined.csv': 'storage/shared/agency_lab/analyses/csv/',
        'f3_timesliced_sources.csv': 'storage/shared/agency_lab/analyses/csv/',
        'f4_rolling_combined.csv': 'storage/shared/agency_lab/analyses/csv/',
        'f4_rolling_sources.csv': 'storage/shared/agency_lab/analyses/csv/'
    }

    restored_count = 0
    for filename, dest_dir in destinations.items():
        source_path = os.path.join(source_dir, filename)
        dest_path = os.path.join(dest_dir, filename)

        if os.path.exists(source_path):
            if not os.path.exists(dest_path):
                shutil.copy(source_path, dest_path)
                print(f"Restored: {dest_path}")
                restored_count += 1
            else:
                print(f"Skipped (already exists): {dest_path}")
        else:
            print(f"ERROR: Source file not found in backup: {source_path}")

    print(f"\n--- RESTORATION COMPLETE: {restored_count} files restored. ---")

if __name__ == "__main__":
    main()
